algorithm SieveOfEratosthenes
    dimension isComposite[101] as boolean;
    define limit as integer;
    define i as integer;
    define j as integer;
    read limit;
    for i <- 0 to 100 step 1 do
        isComposite[i] <- false;
    endFor
    for i <- 2 to limit step 1 do
        if isComposite[i] = false then
            write i;
            for j <- i * i to limit step i do
                isComposite[j] <- true;
            endFor
        endIf
    endFor
endAlgorithm
